const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'src')

const files = {
  "layouts/AdminLayout.vue": "<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\nimport { RouterView, useRoute, useRouter } from 'vue-router'\nimport {\n  WiAvatar,\n  WiBreadcrumb,\n  WiButton,\n  WiDropdown,\n  WiIcon,\n  WiLayout,\n  WiLayoutHeader,\n  WiLayoutSider,\n  WiMenu,\n  WiSpace,\n  useTheme,\n} from '@well-insight/ui'\nimport AppCommandMenu from '@/components/AppCommandMenu.vue'\nimport { adminMenu, menuKeyFromPath, routeByMenuKey } from '@/config/navigation'\nimport { useAuth } from '@/composables/useAuth'\nimport { useLocale } from '@/composables/useLocale'\n\nconst router = useRouter()\nconst route = useRoute()\nconst { user, logout } = useAuth()\nconst { toggleLocale, t } = useLocale()\nconst { isDark, toggleTheme } = useTheme()\n\nconst collapsed = ref(false)\nconst commandOpen = ref(false)\nconst selectedKey = ref<string | null>(menuKeyFromPath(route.path))\n\nwatch(() => route.path, (path) => {\n  selectedKey.value = menuKeyFromPath(path)\n})\n\nconst breadcrumbs = computed(() => {\n  const segments = route.path.split('/').filter(Boolean)\n  const items = [{ label: t('首页', 'Home'), to: '/dashboard' }]\n  const labels: Record<string, string> = {\n    dashboard: t('仪表盘', 'Dashboard'),\n    security: t('权限与安全', 'Security'),\n    academic: t('教务业务', 'Academic'),\n    system: t('系统运营', 'System'),\n    analytics: t('分析报表', 'Analytics'),\n    extras: t('能力增强', 'Extras'),\n    users: t('用户管理', 'Users'),\n    roles: t('角色管理', 'Roles'),\n    permissions: t('权限管理', 'Permissions'),\n    'data-scope': t('数据权限', 'Data Scope'),\n    'audit-logs': t('审计日志', 'Audit Logs'),\n    students: t('学生管理', 'Students'),\n    teachers: t('教师管理', 'Teachers'),\n    courses: t('课程管理', 'Courses'),\n    classes: t('班级管理', 'Classes'),\n    'enrollment-form': t('选课报名', 'Enrollment'),\n    'batch-ops': t('批量操作', 'Batch Ops'),\n    workflow: t('审批流程', 'Workflow'),\n    messages: t('消息中心', 'Messages'),\n    scheduler: t('定时任务', 'Scheduler'),\n    config: t('系统配罾', 'Config'),\n    dictionary: t('字典管理', 'Dictionary'),\n    reports: t('数据报表', 'Reports'),\n    'error-monitor': t('异常监控', 'Errors'),\n    'recycle-bin': t('回收站', 'Recycle Bin'),\n  }\n  let acc = ''\n  for (const seg of segments) {\n    acc += `/${seg}`\n    items.push({ label: labels[seg] || seg, to: acc })\n  }\n  return items\n})\n\nconst userMenu = [\n  { label: t('个人中心', 'Profile'), command: () => router.push('/system/config') },\n  { label: t('退出登录', 'Sign out'), command: logout },\n]\n\nfunction onMenuSelect(item: { key?: string }) {\n  if (!item.key) return\n  const path = routeByMenuKey[item.key]\n  if (path) router.push(path)\n}\n</script>\n\n<template>\n  <WiLayout has-sider class=\"admin-shell\">\n    <WiLayoutSider v-model:collapsed=\"collapsed\" show-trigger bordered class=\"admin-shell__sider\">\n      <div class=\"admin-shell__brand\">\n        <WiIcon name=\"home\" size=\"lg\" aria-hidden=\"true\" />\n        <span v-if=\"!collapsed\" class=\"admin-shell__brand-text\">智学云</span>\n      </div>\n      <WiMenu\n        :model=\"adminMenu\"\n        :selected-key=\"selectedKey\"\n        :collapsed=\"collapsed\"\n        @select=\"onMenuSelect\"\n      />\n    </WiLayoutSider>\n\n    <WiLayout>\n      <WiLayoutHeader bordered class=\"admin-shell__header\">\n        <WiBreadcrumb :model=\"breadcrumbs\" />\n        <WiSpace align=\"center\">\n          <WiButton\n            severity=\"secondary\"\n            size=\"small\"\n            :aria-label=\"t('全局搜索', 'Global search')\"\n            @click=\"commandOpen = true\"\n          >\n            <WiIcon name=\"search\" aria-hidden=\"true\" />\n            <span class=\"admin-shell__search-hint\">Ctrl+K</span>\n          </WiButton>\n          <WiButton\n            severity=\"secondary\"\n            size=\"small\"\n            icon-only\n            :icon=\"isDark ? 'eye-off' : 'eye'\"\n            :aria-label=\"t('切换主题', 'Toggle theme')\"\n            @click=\"toggleTheme\"\n          />\n          <WiButton severity=\"secondary\" size=\"small\" @click=\"toggleLocale\">\n            {{ t('EN', '中') }}\n          </WiButton>\n          <WiDropdown :items=\"userMenu\" trigger=\"click\">\n            <template #trigger>\n              <button type=\"button\" class=\"admin-shell__user\">\n                <WiAvatar :label=\"user?.name?.slice(0, 1) || 'U'\" size=\"sm\" />\n                <span>{{ user?.name }}</span>\n              </button>\n            </template>\n          </WiDropdown>\n        </WiSpace>\n      </WiLayoutHeader>\n\n      <RouterView />\n    </WiLayout>\n  </WiLayout>\n\n  <AppCommandMenu v-model=\"commandOpen\" />\n</template>\n\n<style scoped>\n.admin-shell {\n  min-height: 100vh;\n  background: var(--wi-color-surface);\n}\n\n.admin-shell__sider {\n  background: var(--wi-color-surface);\n}\n\n.admin-shell__brand {\n  display: flex;\n  align-items: center;\n  gap: var(--wi-space-2);\n  padding: var(--wi-space-4) var(--wi-space-4) var(--wi-space-3);\n  color: var(--wi-color-primary);\n  font-weight: 700;\n  font-size: var(--wi-font-size-md);\n}\n\n.admin-shell__brand-text {\n  white-space: nowrap;\n}\n\n.admin-shell__header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--wi-space-4);\n  padding: 0 var(--wi-space-6);\n  min-height: var(--wi-layout-header-height);\n}\n\n.admin-shell__search-hint {\n  margin-left: var(--wi-space-1);\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-xs);\n}\n\n.admin-shell__user {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--wi-space-2);\n  padding: var(--wi-space-1) var(--wi-space-2);\n  border: 1px solid var(--wi-color-border);\n  border-radius: var(--wi-radius-md);\n  background: transparent;\n  color: inherit;\n  cursor: pointer;\n}\n\n.admin-shell__user:hover {\n  background: color-mix(in srgb, var(--wi-color-border) 30%, transparent);\n}\n</style>\n",
  "views/academic/BatchOpsView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport {\n  WiButton,\n  WiCard,\n  WiFileUpload,\n  WiLayoutContent,\n  WiProgressBar,\n  WiSpace,\n  WiTag,\n  useToast,\n} from '@well-insight/ui'\n\nconst toast = useToast()\nconst importing = ref(false)\nconst progress = ref(0)\n\nasync function simulateImport() {\n  importing.value = true\n  progress.value = 0\n  for (let i = 1; i <= 5; i++) {\n    await new Promise((r) => setTimeout(r, 300))\n    progress.value = i * 20\n  }\n  importing.value = false\n  toast.add({ severity: 'success', summary: '导入完成', detail: '成功 128 条，失败 2 条', life: 3500 })\n}\n</script>\n\n<template>\n  <WiLayoutContent class=\"batch-ops\">\n    <h1 class=\"batch-ops__title\">批量操作</h1>\n\n    <div class=\"batch-ops__grid\">\n      <WiCard title=\"批量导入\">\n        <p class=\"batch-ops__desc\">上传 Excel / CSV 批量导入学生、课程或成绩数据。</p>\n        <WiFileUpload mode=\"basic\" accept=\".xlsx,.csv\" />\n        <WiProgressBar v-if=\"importing || progress\" :value=\"progress\" />\n        <WiButton :loading=\"importing\" @click=\"simulateImport\">开始导入</WiButton>\n      </WiCard>\n\n      <WiCard title=\"批量导出\">\n        <p class=\"batch-ops__desc\">按筛选条件导出当前列表数据。</p>\n        <WiSpace wrap>\n          <WiButton severity=\"secondary\">导出 CSV</WiButton>\n          <WiButton severity=\"secondary\">导出 Excel</WiButton>\n          <WiButton severity=\"secondary\">生成 PDF 报表</WiButton>\n        </WiSpace>\n      </WiCard>\n\n      <WiCard title=\"批量导入\">\n        <p class=\"batch-ops__desc\">按筛选条件导出当前列表数据。</p>\n        <WiSpace wrap>\n          <WiTag value=\"已选 0 条\" severity=\"info\" />\n          <WiButton>开始导入</WiButton>\n          <WiButton severity=\"danger\">开始导入</WiButton>\n        </WiSpace>\n      </WiCard>\n    </div>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.batch-ops {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.batch-ops__title {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.batch-ops__grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));\n  gap: var(--wi-space-4);\n}\n\n.batch-ops__desc {\n  margin: 0 0 var(--wi-space-4);\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n</style>\n",
  "views/academic/ClassesView.vue": "<script setup lang=\"ts\">\nimport { WiButton, WiSpace } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { classGroups } from '@/mock'\n\nconst columns = [\n  { key: 'name', label: '班级' },\n  { key: 'grade', label: '年级', width: 88 },\n  { key: 'headTeacher', label: '班主任' },\n  { key: 'students', label: '人数', width: 72 },\n  { key: 'room', label: '教室', width: 88 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"班级管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '教务业务' }, { label: '班级管理' }]\"\n    :columns=\"columns\"\n    :rows=\"classGroups\"\n  >\n    <template #cell-actions>\n      <WiSpace>\n        <WiButton size=\"small\" severity=\"secondary\">花名册</WiButton>\n        <WiButton size=\"small\" severity=\"secondary\">课表</WiButton>\n      </WiSpace>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/academic/CoursesView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { WiButton, WiInput, WiSelect, WiSpace, WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { courses } from '@/mock'\n\nconst keyword = ref('')\nconst category = ref<string | undefined>()\nconst rows = ref(courses)\n\nconst columns = [\n  { key: 'name', label: '课程名称' },\n  { key: 'category', label: '类别' },\n  { key: 'credits', label: '学分', width: 72 },\n  { key: 'teacher', label: '任课教师' },\n  { key: 'enrolled', label: '已选/容量', width: 112 },\n  { key: 'status', label: '状态', width: 88 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"课程管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '教务业务' }, { label: '课程管理' }]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n  >\n    <template #filters>\n      <WiSpace wrap>\n        <WiInput v-model=\"keyword\" placeholder=\"课程名称\" clearable style=\"width: 12rem\" />\n        <WiSelect\n          v-model=\"category\"\n          :options=\"[{ label: '理科', value: '理科' }, { label: '文科', value: '文科' }, { label: '实验', value: '实验' }]\"\n          placeholder=\"类别\"\n          clearable\n          style=\"width: 8rem\"\n        />\n        <WiButton>查询</WiButton>\n      </WiSpace>\n    </template>\n\n    <template #cell-enrolled=\"{ row }\">\n      {{ row.enrolled }} / {{ row.capacity }}\n    </template>\n\n    <template #cell-status=\"{ value }\">\n      <WiTag\n        :value=\"value === 'open' ? '开放' : value === 'full' ? '已满' : '关闭'\"\n        :severity=\"value === 'open' ? 'success' : value === 'full' ? 'warn' : 'secondary'\"\n      />\n    </template>\n\n    <template #cell-actions>\n      <WiButton size=\"small\" severity=\"secondary\">??</WiButton>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/academic/EnrollmentFormView.vue": "<script setup lang=\"ts\">\nimport { computed, reactive, ref } from 'vue'\nimport {\n  WiButton,\n  WiCard,\n  WiDatePicker,\n  WiFileUpload,\n  WiForm,\n  WiFormItem,\n  WiInput,\n  WiLayoutContent,\n  WiSelect,\n  WiSpace,\n  WiSwitch,\n  WiTextarea,\n  useToast,\n} from '@well-insight/ui'\nimport { courses } from '@/mock'\n\nconst toast = useToast()\nconst submitting = ref(false)\nconst draftSaved = ref(false)\n\nconst model = reactive({\n  studentName: '',\n  studentNo: '',\n  courseId: undefined as string | undefined,\n  needMaterial: false,\n  materialNote: '',\n  reason: '',\n  applyDate: null as string | null,\n})\n\nconst courseOptions = courses.map((item) => ({ label: `${item.name} · ${item.teacher}`, value: item.id }))\n\nconst selectedCourse = computed(() => courses.find((item) => item.id === model.courseId))\n\nfunction onCourseChange() {\n  model.needMaterial = selectedCourse.value?.category === '实验'\n}\n\nfunction saveDraft() {\n  localStorage.setItem('edu-enrollment-draft', JSON.stringify(model))\n  draftSaved.value = true\n  toast.add({ severity: 'info', summary: '草稿已保存', life: 2500 })\n}\n\nasync function onSubmit() {\n  submitting.value = true\n  await new Promise((r) => setTimeout(r, 500))\n  submitting.value = false\n  localStorage.removeItem('edu-enrollment-draft')\n  toast.add({ severity: 'success', summary: '选课申请已提交', detail: '请等待教务审核', life: 3000 })\n}\n</script>\n\n<template>\n  <WiLayoutContent class=\"enrollment-form\">\n    <header class=\"enrollment-form__intro\">\n      <h1>选课报名表</h1>\n      <p>填写学生与课程信息，支持上传实验类课程所需材料。</p>\n    </header>\n\n    <WiCard class=\"enrollment-form__card\">\n      <WiForm @submit.prevent=\"onSubmit\">\n        <WiFormItem label=\"学生姓名\" name=\"studentName\" required>\n          <WiInput v-model=\"model.studentName\" fluid />\n        </WiFormItem>\n        <WiFormItem label=\"学号\" name=\"studentNo\" required>\n          <WiInput v-model=\"model.studentNo\" fluid />\n        </WiFormItem>\n        <WiFormItem label=\"学生姓名\" name=\"courseId\" required>\n          <WiSelect\n            v-model=\"model.courseId\"\n            :options=\"courseOptions\"\n            placeholder=\"请选择课程\"\n            fluid\n            @update:model-value=\"onCourseChange\"\n          />\n        </WiFormItem>\n\n        <WiFormItem v-if=\"model.needMaterial\" label=\"上传材料\" name=\"material\">\n          <WiFileUpload mode=\"basic\" accept=\".pdf,.jpg,.png\" />\n          <WiTextarea v-model=\"model.materialNote\" :rows=\"2\" placeholder=\"材料说明（可选）\" fluid />\n        </WiFormItem>\n\n        <WiFormItem label=\"学生姓名\" name=\"applyDate\">\n          <WiDatePicker v-model=\"model.applyDate\" fluid />\n        </WiFormItem>\n\n        <WiFormItem label=\"学生姓名\" name=\"reason\">\n          <WiTextarea v-model=\"model.reason\" :rows=\"4\" fluid />\n        </WiFormItem>\n\n        <WiFormItem label=\"上传材料\" name=\"notify\">\n          <WiSwitch :model-value=\"true\" />\n        </WiFormItem>\n\n        <footer class=\"enrollment-form__actions\">\n          <WiSpace>\n            <WiButton native-type=\"submit\" :loading=\"submitting\">提交申请</WiButton>\n            <WiButton severity=\"secondary\" @click=\"saveDraft\">提交申请</WiButton>\n            <WiButton severity=\"secondary\">取消</WiButton>\n          </WiSpace>\n          <p v-if=\"draftSaved\" class=\"enrollment-form__draft-hint\">草稿已保存至 localStorage</p>\n        </footer>\n      </WiForm>\n    </WiCard>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.enrollment-form {\n  padding: var(--wi-space-6);\n  max-width: 42rem;\n}\n\n.enrollment-form__intro h1 {\n  margin: 0 0 var(--wi-space-2);\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.enrollment-form__intro p {\n  margin: 0 0 var(--wi-space-4);\n  color: var(--wi-color-text-muted);\n}\n\n.enrollment-form__card {\n  padding: var(--wi-space-2);\n}\n\n.enrollment-form__actions {\n  margin-top: var(--wi-space-4);\n  padding-top: var(--wi-space-4);\n  border-top: 1px solid var(--wi-color-border);\n}\n\n.enrollment-form__draft-hint {\n  margin: var(--wi-space-2) 0 0;\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n</style>\n",
  "views/academic/StudentsView.vue": "<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { WiButton, WiInput, WiSelect, WiSpace, WiTag, useToast } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { students } from '@/mock'\n\nconst toast = useToast()\nconst keyword = ref('')\nconst grade = ref<string | undefined>()\nconst status = ref<string | undefined>()\nconst selection = ref<unknown[] | null>(null)\nconst visibleColumns = ref(['name', 'studentNo', 'grade', 'className', 'status', 'enrolledAt'])\n\nconst allColumns = [\n  { key: 'name', label: '姓名' },\n  { key: 'studentNo', label: '学号' },\n  { key: 'grade', label: '年级' },\n  { key: 'className', label: '班级' },\n  { key: 'status', label: '状态' },\n  { key: 'enrolledAt', label: '入学日期' },\n  { key: 'actions', label: '操作', width: 140 },\n]\n\nconst columns = computed(() => allColumns.filter((col) => visibleColumns.value.includes(col.key) || col.key === 'actions'))\n\nconst rows = computed(() =>\n  students.filter((row) => {\n    const matchKeyword = !keyword.value || row.name.includes(keyword.value) || row.studentNo.includes(keyword.value)\n    const matchGrade = !grade.value || row.grade === grade.value\n    const matchStatus = !status.value || row.status === status.value\n    return matchKeyword && matchGrade && matchStatus\n  }),\n)\n\nfunction toggleColumn(key: string) {\n  if (key === 'actions') return\n  if (visibleColumns.value.includes(key)) {\n    visibleColumns.value = visibleColumns.value.filter((item) => item !== key)\n  } else {\n    visibleColumns.value = [...visibleColumns.value, key]\n  }\n}\n</script>\n\n<template>\n  <ListPageTemplate\n    v-model:selection=\"selection\"\n    title=\"学生管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '教务业务' }, { label: '学生管理' }]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n    selection-mode=\"multiple\"\n    :rows-per-page=\"5\"\n  >\n    <template #filters>\n      <WiSpace wrap>\n        <WiInput v-model=\"keyword\" placeholder=\"姓名 / 学号\" clearable style=\"width: 12rem\" />\n        <WiSelect\n          v-model=\"grade\"\n          :options=\"[{ label: '高一', value: '高一' }, { label: '高二', value: '高二' }, { label: '高三', value: '高三' }]\"\n          placeholder=\"年级\"\n          clearable\n          style=\"width: 8rem\"\n        />\n        <WiSelect\n          v-model=\"status\"\n          :options=\"[{ label: '在读', value: 'active' }, { label: '休学', value: 'leave' }, { label: '毕业', value: 'graduated' }]\"\n          placeholder=\"状态\"\n          clearable\n          style=\"width: 8rem\"\n        />\n        <WiButton>查询</WiButton>\n        <WiButton severity=\"secondary\">重置</WiButton>\n      </WiSpace>\n      <WiSpace wrap class=\"students-page__columns\">\n        <span class=\"students-page__columns-label\">显示列</span>\n        <WiButton\n          v-for=\"col in allColumns.filter((c) => c.key !== 'actions')\"\n          :key=\"col.key\"\n          size=\"small\"\n          :severity=\"visibleColumns.includes(col.key) ? undefined : 'secondary'\"\n          @click=\"toggleColumn(col.key)\"\n        >\n          {{ col.label }}\n        </WiButton>\n      </WiSpace>\n    </template>\n\n    <template #actions>\n      <WiButton severity=\"secondary\" @click=\"toast.add({ severity: 'info', summary: '演示：CSV 导出已触发' })\">\n        ??\n      </WiButton>\n    </template>\n\n    <template #cell-status=\"{ value }\">\n      <WiTag\n        :value=\"value === 'active' ? '在读' : value === 'leave' ? '休学' : '毕业'\"\n        :severity=\"value === 'active' ? 'success' : value === 'leave' ? 'warn' : 'secondary'\"\n      />\n    </template>\n\n    <template #cell-actions>\n      <WiSpace>\n        <WiButton size=\"small\" severity=\"secondary\">编辑</WiButton>\n        <WiButton size=\"small\" severity=\"danger\">删除</WiButton>\n      </WiSpace>\n    </template>\n  </ListPageTemplate>\n</template>\n\n<style scoped>\n.students-page__columns {\n  margin-top: var(--wi-space-3);\n}\n\n.students-page__columns-label {\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n</style>\n",
  "views/academic/TeachersView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { WiButton, WiInput, WiSpace, WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { teachers } from '@/mock'\n\nconst keyword = ref('')\nconst rows = ref(teachers)\n\nconst columns = [\n  { key: 'name', label: '姓名' },\n  { key: 'title', label: '职称' },\n  { key: 'department', label: '院系' },\n  { key: 'courses', label: '课程数', width: 88 },\n  { key: 'status', label: '状态', width: 88 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"教师管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '教务业务' }, { label: '教师管理' }]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n  >\n    <template #filters>\n      <WiSpace wrap>\n        <WiInput v-model=\"keyword\" placeholder=\"姓名关键词\" clearable style=\"width: 12rem\" />\n        <WiButton>查询</WiButton>\n      </WiSpace>\n    </template>\n\n    <template #cell-status=\"{ value }\">\n      <WiTag :value=\"value === 'active' ? '在职' : '离职'\" :severity=\"value === 'active' ? 'success' : 'secondary'\" />\n    </template>\n\n    <template #cell-actions>\n      <WiButton size=\"small\" severity=\"secondary\">详情</WiButton>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/academic/WorkflowView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport {\n  WiButton,\n  WiCard,\n  WiLayoutContent,\n  WiProgressBar,\n  WiStepper,\n  WiTable,\n  WiTag,\n  WiTimeline,\n} from '@well-insight/ui'\nimport { workflowTasks } from '@/mock'\n\nconst activeStep = ref(1)\n\nconst steps = [\n  { label: '提交申请', description: '教师 / 学生' },\n  { label: '教务审核', description: '教务' },\n  { label: '院系审批', description: '院长' },\n  { label: '归档', description: '系统' },\n]\n\nconst columns = [\n  { key: 'title', label: '标题' },\n  { key: 'applicant', label: '申请人', width: 96 },\n  { key: 'step', label: '当前节点', width: 112 },\n  { key: 'status', label: '状态', width: 96 },\n  { key: 'updatedAt', label: '更新时间', width: 140 },\n]\n\nconst timeline = [\n  { content: '申请已提交', date: '2026-09-02 09:00', severity: 'info' as const },\n  { content: '教务审核通过', date: '2026-09-02 10:15', severity: 'success' as const },\n  { content: '等待院系审批', date: '待定', severity: 'warn' as const },\n]\n</script>\n\n<template>\n  <WiLayoutContent class=\"workflow-page\">\n    <h1 class=\"workflow-page__title\">审批流程</h1>\n\n    <WiCard title=\"流程进度示意\">\n      <WiStepper v-model=\"activeStep\" :steps=\"steps\" />\n      <WiProgressBar :value=\"((activeStep + 1) / steps.length) * 100\" />\n    </WiCard>\n\n    <div class=\"workflow-page__split\">\n      <WiCard title=\"待办列表\">\n        <WiTable :columns=\"columns\" :rows=\"workflowTasks as unknown as Record<string, unknown>[]\" striped bordered :paginator=\"false\">\n          <template #cell-status=\"{ value }\">\n            <WiTag\n              :value=\"value === 'pending' ? '待审批' : value === 'approved' ? '已通过' : '已驳回'\"\n              :severity=\"value === 'pending' ? 'warn' : value === 'approved' ? 'success' : 'danger'\"\n            />\n          </template>\n        </WiTable>\n      </WiCard>\n\n      <WiCard title=\"最近动态（示例）\">\n        <WiTimeline :value=\"timeline\" />\n        <WiButton style=\"margin-top: var(--wi-space-4)\">刷新</WiButton>\n      </WiCard>\n    </div>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.workflow-page {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.workflow-page__title {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.workflow-page__split {\n  display: grid;\n  grid-template-columns: 1.2fr 0.8fr;\n  gap: var(--wi-space-4);\n}\n\n@media (max-width: 56rem) {\n  .workflow-page__split {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "views/security/UsersView.vue": "<script setup lang=\"ts\">\nimport { WiButton, WiSpace, WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\n\nconst rows = [\n  { id: 'u1', name: '张管理员', email: 'admin@educloud.cn', role: '超级管理员', status: 'active', lastLogin: '2026-09-02 08:30' },\n  { id: 'u2', name: '李老师', email: 'li@educloud.cn', role: '教务主任', status: 'active', lastLogin: '2026-09-01 17:20' },\n  { id: 'u3', name: '王班主任', email: 'wang@educloud.cn', role: '班主任', status: 'inactive', lastLogin: '2026-08-28 09:10' },\n]\n\nconst columns = [\n  { key: 'name', label: '姓名' },\n  { key: 'email', label: '邮箱' },\n  { key: 'role', label: '角色' },\n  { key: 'status', label: '状态', width: 88 },\n  { key: 'lastLogin', label: '最近登录', width: 140 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"用户管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '权限与安全' }, { label: '用户管理' }]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n  >\n    <template #cell-status=\"{ value }\">\n      <WiTag :value=\"value === 'active' ? '正常' : '停用'\" :severity=\"value === 'active' ? 'success' : 'secondary'\" />\n    </template>\n    <template #cell-actions>\n      <WiSpace>\n        <WiButton size=\"small\" severity=\"secondary\">编辑</WiButton>\n        <WiButton size=\"small\" severity=\"danger\">禁用</WiButton>\n      </WiSpace>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/security/RolesView.vue": "<script setup lang=\"ts\">\nimport { WiButton, WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { roles } from '@/mock'\n\nconst columns = [\n  { key: 'name', label: '角色名称' },\n  { key: 'code', label: '编码' },\n  { key: 'users', label: '用户数', width: 88 },\n  { key: 'permissions', label: '权限范围' },\n  { key: 'status', label: '状态', width: 88 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"角色管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '权限与安全' }, { label: '角色管理' }]\"\n    :columns=\"columns\"\n    :rows=\"roles\"\n  >\n    <template #cell-status=\"{ value }\">\n      <WiTag :value=\"value === 'active' ? '启用' : '停用'\" :severity=\"value === 'active' ? 'success' : 'secondary'\" />\n    </template>\n    <template #cell-actions>\n      <WiButton size=\"small\" severity=\"secondary\">分配权限</WiButton>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/security/PermissionsView.vue": "<script setup lang=\"ts\">\nimport { WiCard, WiLayoutContent, WiTable, WiTag } from '@well-insight/ui'\nimport { permissions } from '@/mock'\n\nconst columns = [\n  { key: 'name', label: '权限名称' },\n  { key: 'code', label: '标识' },\n  { key: 'type', label: '类型', width: 88 },\n  { key: 'module', label: '模块', width: 96 },\n]\n</script>\n\n<template>\n  <WiLayoutContent class=\"permissions-page\">\n    <h1>权限清单（RBAC）</h1>\n    <p class=\"permissions-page__desc\">菜单、按钮与 API 权限统一管理。</p>\n    <WiCard>\n      <WiTable :columns=\"columns\" :rows=\"permissions as unknown as Record<string, unknown>[]\" striped bordered :paginator=\"false\">\n        <template #cell-type=\"{ value }\">\n          <WiTag\n            :value=\"value === 'menu' ? '菜单' : value === 'button' ? '按钮' : '接口'\"\n            :severity=\"value === 'menu' ? 'info' : value === 'button' ? 'warn' : 'secondary'\"\n          />\n        </template>\n      </WiTable>\n    </WiCard>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.permissions-page {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.permissions-page h1 {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.permissions-page__desc {\n  margin: 0;\n  color: var(--wi-color-text-muted);\n}\n</style>\n",
  "views/security/DataScopeView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport {\n  WiButton,\n  WiCard,\n  WiForm,\n  WiFormItem,\n  WiLayoutContent,\n  WiRadio,\n  WiRadioGroup,\n  WiSelect,\n  WiSpace,\n} from '@well-insight/ui'\n\nconst scope = ref('department')\nconst department = ref('math')\n</script>\n\n<template>\n  <WiLayoutContent class=\"data-scope\">\n    <h1>数据权限</h1>\n    <p class=\"data-scope__desc\">配置角色可访问的数据范围，支持按院系隔离。</p>\n\n    <WiCard title=\"??? � ??????\">\n      <WiForm label-position=\"top\">\n        <WiFormItem label=\"数据范围\" name=\"scope\">\n          <WiRadioGroup v-model=\"scope\">\n            <WiSpace vertical>\n              <WiRadio value=\"self\" label=\"仅本人数据\" />\n              <WiRadio value=\"department\" label=\"本部门数据\" />\n              <WiRadio value=\"all\" label=\"数据范围\" />\n            </WiSpace>\n          </WiRadioGroup>\n        </WiFormItem>\n        <WiFormItem v-if=\"scope === 'department'\" label=\"数据范围\" name=\"department\">\n          <WiSelect\n            v-model=\"department\"\n            :options=\"[\n              { label: '数学组', value: 'math' },\n              { label: '语文组', value: 'chinese' },\n              { label: '英语组', value: 'english' },\n            ]\"\n            fluid\n          />\n        </WiFormItem>\n        <WiSpace>\n          <WiButton>保存配置</WiButton>\n          <WiButton severity=\"secondary\">保存配置</WiButton>\n        </WiSpace>\n      </WiForm>\n    </WiCard>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.data-scope {\n  padding: var(--wi-space-6);\n  max-width: 40rem;\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.data-scope h1 {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.data-scope__desc {\n  margin: 0;\n  color: var(--wi-color-text-muted);\n}\n</style>\n",
  "views/security/AuditLogsView.vue": "<script setup lang=\"ts\">\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { auditLogs } from '@/mock'\n\nconst columns = [\n  { key: 'operator', label: '操作人' },\n  { key: 'action', label: '动作', width: 88 },\n  { key: 'target', label: '对象' },\n  { key: 'ip', label: 'IP', width: 120 },\n  { key: 'time', label: '时间', width: 140 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"审计日志\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '权限与安全' }, { label: '审计日志' }]\"\n    :columns=\"columns\"\n    :rows=\"auditLogs\"\n    :paginator=\"false\"\n  />\n</template>\n",
  "views/system/MessageCenterView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { WiButton, WiCard, WiLayoutContent, WiTable, WiTabs, WiTag } from '@well-insight/ui'\nimport { messages } from '@/mock'\n\nconst columns = [\n  { key: 'channel', label: '渠道', width: 88 },\n  { key: 'title', label: '标题' },\n  { key: 'template', label: '模板', width: 140 },\n  { key: 'sentAt', label: '发送时间', width: 140 },\n  { key: 'status', label: '状态', width: 88 },\n]\n\nconst tab = ref('records')\n</script>\n\n<template>\n  <WiLayoutContent class=\"messages-page\">\n    <h1>消息中心</h1>\n    <WiTabs\n      v-model=\"tab\"\n      :tabs=\"[\n        { label: '发送记录', value: 'records' },\n        { label: '消息模板', value: 'templates' },\n      ]\"\n    />\n    <WiCard v-if=\"tab === 'records'\">\n      <WiTable :columns=\"columns\" :rows=\"messages as unknown as Record<string, unknown>[]\" striped bordered paginator>\n        <template #cell-status=\"{ value }\">\n          <WiTag\n            :value=\"value === 'success' ? '成功' : value === 'failed' ? '失败' : '排队中'\"\n            :severity=\"value === 'success' ? 'success' : value === 'failed' ? 'danger' : 'warn'\"\n          />\n        </template>\n      </WiTable>\n    </WiCard>\n    <WiCard v-else title=\"模板管理\">\n      <p class=\"messages-page__desc\">维护站内信、短信与邮件模板。</p>\n      <WiButton>新建模板</WiButton>\n    </WiCard>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.messages-page {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.messages-page h1 {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.messages-page__desc {\n  margin: 0 0 var(--wi-space-4);\n  color: var(--wi-color-text-muted);\n}\n</style>\n",
  "views/system/SchedulerView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { WiButton, WiSpace, WiTag, useToast } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { schedulerJobs } from '@/mock'\n\nconst toast = useToast()\nconst rows = ref(schedulerJobs)\n\nconst columns = [\n  { key: 'name', label: '任务名称' },\n  { key: 'cron', label: 'Cron', width: 120 },\n  { key: 'lastRun', label: '上次执行', width: 140 },\n  { key: 'nextRun', label: '下次执行', width: 140 },\n  { key: 'status', label: '状态', width: 96 },\n  { key: 'actions', label: '操作', width: 160 },\n]\n\nfunction runNow(id: string) {\n  toast.add({ severity: 'success', summary: '任务已触发', detail: id, life: 2500 })\n}\n\nfunction togglePause(row: { id: string; status: string }) {\n  row.status = row.status === 'paused' ? 'idle' : 'paused'\n}\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"定时任务\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '系统运营' }, { label: '定时任务' }]\"\n    :columns=\"columns\"\n    :rows=\"rows\"\n    :paginator=\"false\"\n  >\n    <template #cell-status=\"{ value }\">\n      <WiTag\n        :value=\"value === 'running' ? '运行中' : value === 'paused' ? '已暂停' : '空闲'\"\n        :severity=\"value === 'running' ? 'success' : value === 'paused' ? 'warn' : 'info'\"\n      />\n    </template>\n    <template #cell-actions=\"{ row }\">\n      <WiSpace>\n        <WiButton size=\"small\" severity=\"secondary\" @click=\"runNow(row.id)\">立即执行</WiButton>\n        <WiButton size=\"small\" severity=\"secondary\" @click=\"togglePause(row)\">\n          {{ row.status === 'paused' ? '恢复' : '暂停' }}\n        </WiButton>\n      </WiSpace>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/system/DictionaryView.vue": "<script setup lang=\"ts\">\nimport { WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { dictionaries } from '@/mock'\n\nconst columns = [\n  { key: 'type', label: '字典类型', width: 140 },\n  { key: 'label', label: '显示名' },\n  { key: 'value', label: '值', width: 120 },\n  { key: 'sort', label: '排序', width: 72 },\n  { key: 'status', label: '状态', width: 88 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"字典管理\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '系统运营' }, { label: '字典管理' }]\"\n    :columns=\"columns\"\n    :rows=\"dictionaries\"\n    :paginator=\"false\"\n  >\n    <template #cell-status=\"{ value }\">\n      <WiTag :value=\"value === 'enabled' ? '启用' : '停用'\" :severity=\"value === 'enabled' ? 'success' : 'secondary'\" />\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/analytics/ReportsView.vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { WiButton, WiCard, WiGrid, WiGridItem, WiLayoutContent, WiSelect, WiSpace } from '@well-insight/ui'\nimport { enrollmentTrend, gradeDistribution } from '@/mock'\n\nconst dimension = ref('grade')\nconst maxTrend = Math.max(...enrollmentTrend.map((item) => item.count))\n</script>\n\n<template>\n  <WiLayoutContent class=\"reports-page\">\n    <header class=\"reports-page__header\">\n      <h1>数据报表</h1>\n      <WiSpace>\n        <WiSelect\n          v-model=\"dimension\"\n          :options=\"[\n            { label: '按年级', value: 'grade' },\n            { label: '按院系', value: 'department' },\n            { label: '按月份', value: 'month' },\n          ]\"\n          style=\"width: 10rem\"\n        />\n        <WiButton severity=\"secondary\">导出 Excel</WiButton>\n        <WiButton severity=\"secondary\">导出 PDF</WiButton>\n      </WiSpace>\n    </header>\n\n    <WiGrid :cols=\"2\" :x-gap=\"16\" :y-gap=\"16\">\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"选课趋势\">\n          <div class=\"reports-page__bars\">\n            <div v-for=\"item in enrollmentTrend\" :key=\"item.month\" class=\"reports-page__bar-item\">\n              <div class=\"reports-page__bar\" :style=\"{ height: `${(item.count / maxTrend) * 100}%` }\" />\n              <span>{{ item.month }}</span>\n            </div>\n          </div>\n        </WiCard>\n      </WiGridItem>\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"选课趋势\">\n          <ul class=\"reports-page__list\">\n            <li v-for=\"item in gradeDistribution\" :key=\"item.grade\">\n              <span>{{ item.grade }}</span>\n              <strong>{{ item.count }}</strong>\n            </li>\n          </ul>\n        </WiCard>\n      </WiGridItem>\n    </WiGrid>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.reports-page {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-4);\n}\n\n.reports-page__header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--wi-space-4);\n  flex-wrap: wrap;\n}\n\n.reports-page__header h1 {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.reports-page__bars {\n  display: flex;\n  align-items: flex-end;\n  gap: var(--wi-space-3);\n  min-height: 10rem;\n}\n\n.reports-page__bar-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: var(--wi-space-2);\n  height: 10rem;\n  justify-content: flex-end;\n  font-size: var(--wi-font-size-xs);\n  color: var(--wi-color-text-muted);\n}\n\n.reports-page__bar {\n  width: 100%;\n  max-width: 2.5rem;\n  border-radius: var(--wi-radius-sm) var(--wi-radius-sm) 0 0;\n  background: color-mix(in srgb, var(--wi-color-primary) 70%, transparent);\n}\n\n.reports-page__list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: grid;\n  gap: var(--wi-space-3);\n}\n\n.reports-page__list li {\n  display: flex;\n  justify-content: space-between;\n  padding: var(--wi-space-3);\n  border: 1px solid var(--wi-color-border);\n  border-radius: var(--wi-radius-md);\n}\n</style>\n",
  "views/analytics/ErrorMonitorView.vue": "<script setup lang=\"ts\">\nimport { WiTag } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { errorRecords } from '@/mock'\n\nconst columns = [\n  { key: 'endpoint', label: '接口' },\n  { key: 'code', label: '状态码', width: 88 },\n  { key: 'message', label: '错误信息' },\n  { key: 'count', label: '次数', width: 72 },\n  { key: 'lastSeen', label: '最近出现', width: 140 },\n]\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"异常监控\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '分析报表' }, { label: '异常监控' }]\"\n    :columns=\"columns\"\n    :rows=\"errorRecords\"\n    :paginator=\"false\"\n  >\n    <template #cell-code=\"{ value }\">\n      <WiTag :value=\"String(value)\" :severity=\"Number(value) >= 500 ? 'danger' : 'warn'\" />\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/extras/RecycleBinView.vue": "<script setup lang=\"ts\">\nimport { WiButton, WiSpace, useToast } from '@well-insight/ui'\nimport ListPageTemplate from '@/components/ListPageTemplate.vue'\nimport { recycleBin } from '@/mock'\n\nconst toast = useToast()\n\nconst columns = [\n  { key: 'name', label: '名称' },\n  { key: 'module', label: '模块', width: 112 },\n  { key: 'deletedBy', label: '删除人', width: 96 },\n  { key: 'deletedAt', label: '删除时间', width: 112 },\n  { key: 'expireAt', label: '过期时间', width: 112 },\n  { key: 'actions', label: '操作', width: 120 },\n]\n\nfunction restore(name: string) {\n  toast.add({ severity: 'success', summary: '已恢复', detail: name, life: 2500 })\n}\n</script>\n\n<template>\n  <ListPageTemplate\n    title=\"回收站\"\n    :breadcrumbs=\"[{ label: '首页', to: '/dashboard' }, { label: '能力增强' }, { label: '回收站' }]\"\n    :columns=\"columns\"\n    :rows=\"recycleBin\"\n    :paginator=\"false\"\n  >\n    <template #cell-actions=\"{ row }\">\n      <WiSpace>\n        <WiButton size=\"small\" @click=\"restore(row.name)\">恢复</WiButton>\n        <WiButton size=\"small\" severity=\"danger\">彻底删除</WiButton>\n      </WiSpace>\n    </template>\n  </ListPageTemplate>\n</template>\n",
  "views/auth/LoginView.vue": "<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useRoute, useRouter } from 'vue-router'\nimport {\n  WiButton,\n  WiCard,\n  WiForm,\n  WiFormItem,\n  WiInput,\n  WiInputOtp,\n  WiMessage,\n  WiSpace,\n  WiTabs,\n  useToast,\n} from '@well-insight/ui'\nimport { useAuth } from '@/composables/useAuth'\n\nconst router = useRouter()\nconst route = useRoute()\nconst { login, verifyMfa, mfaVerified, user } = useAuth()\nconst toast = useToast()\n\nconst tab = ref('password')\nconst account = ref('admin')\nconst password = ref('admin123')\nconst otp = ref('')\nconst loading = ref(false)\nconst error = ref('')\n\nconst showMfa = computed(() => route.query.mfa === '1' || (user.value && !mfaVerified.value))\n\nasync function onLogin() {\n  loading.value = true\n  error.value = ''\n  try {\n    await login({ account: account.value, password: password.value })\n    toast.add({ severity: 'success', summary: '登录成功', detail: '欢迎回来', life: 3000 })\n    router.push('/dashboard')\n  } catch (err) {\n    const message = err instanceof Error ? err.message : '登录失败'\n    if (message === 'MFA_REQUIRED') {\n      router.replace('/login?mfa=1')\n      error.value = '需要 MFA 验证，演示验证码 123456'\n    } else {\n      error.value = message\n    }\n  } finally {\n    loading.value = false\n  }\n}\n\nasync function onVerifyMfa() {\n  loading.value = true\n  error.value = ''\n  try {\n    await verifyMfa(otp.value)\n    toast.add({ severity: 'success', summary: '验证成功', life: 2500 })\n    router.push('/dashboard')\n  } catch (err) {\n    error.value = err instanceof Error ? err.message : '验证失败'\n  } finally {\n    loading.value = false\n  }\n}\n</script>\n\n<template>\n  <WiCard class=\"login-page\">\n    <header class=\"login-page__header\">\n      <h1>智学云 · 教育管理后台</h1>\n      <p>演示账号 admin / admin123 · MFA 123456</p>\n    </header>\n\n    <WiMessage v-if=\"error\" severity=\"error\" :closable=\"false\">{{ error }}</WiMessage>\n\n    <template v-if=\"showMfa\">\n      <WiForm @submit.prevent=\"onVerifyMfa\">\n        <WiFormItem label=\"MFA 验证码\" name=\"otp\" required>\n          <WiInputOtp v-model=\"otp\" :length=\"6\" />\n        </WiFormItem>\n        <WiButton native-type=\"submit\" fluid :loading=\"loading\">完成验证</WiButton>\n      </WiForm>\n    </template>\n\n    <template v-else>\n      <WiTabs v-model=\"tab\" :tabs=\"[{ label: '账号密码', value: 'password' }, { label: '邮箱验证码', value: 'otp' }]\" />\n      <WiForm @submit.prevent=\"onLogin\">\n        <WiFormItem label=\"账号\" name=\"account\" required>\n          <WiInput v-model=\"account\" placeholder=\"admin / teacher\" fluid />\n        </WiFormItem>\n        <WiFormItem v-if=\"tab === 'password'\" label=\"密码\" name=\"password\" required>\n          <WiInput v-model=\"password\" type=\"password\" fluid />\n        </WiFormItem>\n        <WiFormItem v-else label=\"邮箱验证码\" name=\"emailOtp\">\n          <WiSpace>\n            <WiInput placeholder=\"name@educloud.cn\" fluid />\n            <WiButton severity=\"secondary\">获取验证码</WiButton>\n          </WiSpace>\n        </WiFormItem>\n        <WiButton native-type=\"submit\" fluid :loading=\"loading\">登录</WiButton>\n      </WiForm>\n      <p class=\"login-page__footer\">\n        还没有账号？\n        <RouterLink to=\"/register\">注册</RouterLink>\n      </p>\n    </template>\n  </WiCard>\n</template>\n\n<style scoped>\n.login-page {\n  width: min(100%, 26rem);\n  padding: var(--wi-space-6);\n  box-shadow: var(--wi-shadow-md);\n}\n\n.login-page__header h1 {\n  margin: 0 0 var(--wi-space-2);\n  font-size: var(--wi-font-size-lg);\n}\n\n.login-page__header p {\n  margin: 0 0 var(--wi-space-4);\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n\n.login-page__footer {\n  margin: var(--wi-space-4) 0 0;\n  text-align: center;\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n\n.login-page__footer a {\n  color: var(--wi-color-primary);\n}\n</style>\n",
  "views/auth/RegisterView.vue": "<script setup lang=\"ts\">\nimport { reactive, ref } from 'vue'\nimport { useRouter } from 'vue-router'\nimport {\n  WiButton,\n  WiCard,\n  WiForm,\n  WiFormItem,\n  WiInput,\n  useToast,\n} from '@well-insight/ui'\nimport { useAuth } from '@/composables/useAuth'\n\nconst router = useRouter()\nconst { register } = useAuth()\nconst toast = useToast()\nconst loading = ref(false)\n\nconst model = reactive({\n  name: '',\n  email: '',\n  password: '',\n  confirm: '',\n})\n\nasync function onSubmit() {\n  if (model.password !== model.confirm) {\n    toast.add({ severity: 'warn', summary: '两次密码不一致', life: 3000 })\n    return\n  }\n  loading.value = true\n  try {\n    await register({ name: model.name, email: model.email, password: model.password })\n    toast.add({ severity: 'success', summary: '注册成功', life: 2500 })\n    router.push('/dashboard')\n  } catch (err) {\n    toast.add({\n      severity: 'error',\n      summary: '注册失败',\n      detail: err instanceof Error ? err.message : undefined,\n      life: 3500,\n    })\n  } finally {\n    loading.value = false\n  }\n}\n</script>\n\n<template>\n  <WiCard class=\"register-page\">\n    <header class=\"register-page__header\">\n      <h1>注册智学云账号</h1>\n      <p>演示注册，数据保存在 localStorage</p>\n    </header>\n    <WiForm @submit.prevent=\"onSubmit\">\n      <WiFormItem label=\"姓名\" name=\"name\" required>\n        <WiInput v-model=\"model.name\" fluid />\n      </WiFormItem>\n      <WiFormItem label=\"姓名\" name=\"email\" required>\n        <WiInput v-model=\"model.email\" type=\"email\" fluid />\n      </WiFormItem>\n      <WiFormItem label=\"姓名\" name=\"password\" required>\n        <WiInput v-model=\"model.password\" type=\"password\" fluid />\n      </WiFormItem>\n      <WiFormItem label=\"确认密码\" name=\"confirm\" required>\n        <WiInput v-model=\"model.confirm\" type=\"password\" fluid />\n      </WiFormItem>\n      <WiButton native-type=\"submit\" fluid :loading=\"loading\">提交注册</WiButton>\n    </WiForm>\n    <p class=\"register-page__footer\">\n      已有账号？\n      <RouterLink to=\"/login\">去登录</RouterLink>\n    </p>\n  </WiCard>\n</template>\n\n<style scoped>\n.register-page {\n  width: min(100%, 26rem);\n  padding: var(--wi-space-6);\n  box-shadow: var(--wi-shadow-md);\n}\n\n.register-page__header h1 {\n  margin: 0 0 var(--wi-space-2);\n  font-size: var(--wi-font-size-lg);\n}\n\n.register-page__header p {\n  margin: 0 0 var(--wi-space-4);\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n\n.register-page__footer {\n  margin-top: var(--wi-space-4);\n  text-align: center;\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n\n.register-page__footer a {\n  color: var(--wi-color-primary);\n}\n</style>\n",
  "views/dashboard/DashboardView.vue": "<script setup lang=\"ts\">\nimport type { IconName } from '@well-insight/ui'\nimport {\n  WiCard,\n  WiGrid,\n  WiGridItem,\n  WiIcon,\n  WiLayoutContent,\n  WiSpace,\n  WiTable,\n  WiTag,\n} from '@well-insight/ui'\nimport {\n  courses,\n  dashboardStats,\n  enrollmentTrend,\n  gradeDistribution,\n  workflowTasks,\n} from '@/mock'\n\nconst stats: Array<{ label: string; value: string; trend: string; icon: IconName }> = [\n  { label: '在校学生', value: dashboardStats.students.toLocaleString(), trend: '+3.2%', icon: 'user' },\n  { label: '在职教师', value: String(dashboardStats.teachers), trend: '+1', icon: 'user' },\n  { label: '开设课程', value: String(dashboardStats.courses), trend: '+6', icon: 'star' },\n  { label: '选课完成率', value: `${dashboardStats.enrollmentRate}%`, trend: '+2.1%', icon: 'sort' },\n]\n\nconst recentColumns = [\n  { key: 'title', label: '标题' },\n  { key: 'applicant', label: '申请人', width: 96 },\n  { key: 'status', label: '状态', width: 96 },\n]\n\nconst maxTrend = Math.max(...enrollmentTrend.map((item) => item.count))\n</script>\n\n<template>\n  <WiLayoutContent class=\"dashboard\">\n    <h1 class=\"dashboard__title\">智学云 · 教务概览</h1>\n\n    <WiGrid :cols=\"4\" :x-gap=\"16\" :y-gap=\"16\" responsive=\"screen\">\n      <WiGridItem v-for=\"item in stats\" :key=\"item.label\" :span=\"1\">\n        <WiCard class=\"dashboard__stat\">\n          <WiSpace align=\"center\" justify=\"space-between\">\n            <div>\n              <p class=\"dashboard__stat-label\">{{ item.label }}</p>\n              <p class=\"dashboard__stat-value\">{{ item.value }}</p>\n              <p class=\"dashboard__stat-trend\">{{ item.trend }}</p>\n            </div>\n            <WiIcon :name=\"item.icon\" size=\"lg\" class=\"dashboard__stat-icon\" aria-hidden=\"true\" />\n          </WiSpace>\n        </WiCard>\n      </WiGridItem>\n    </WiGrid>\n\n    <WiGrid :cols=\"2\" :x-gap=\"16\" :y-gap=\"16\">\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"近 6 个月选课趋势\">\n          <div class=\"dashboard__bars\" role=\"img\" aria-label=\"选课趋势柱状图\">\n            <div v-for=\"item in enrollmentTrend\" :key=\"item.month\" class=\"dashboard__bar-item\">\n              <div\n                class=\"dashboard__bar\"\n                :style=\"{ height: `${(item.count / maxTrend) * 100}%` }\"\n              />\n              <span>{{ item.month }}</span>\n            </div>\n          </div>\n        </WiCard>\n      </WiGridItem>\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"年级人数\">\n          <ul class=\"dashboard__grades\">\n            <li v-for=\"item in gradeDistribution\" :key=\"item.grade\">\n              <span>{{ item.grade }}</span>\n              <strong>{{ item.count }}</strong>\n            </li>\n          </ul>\n        </WiCard>\n      </WiGridItem>\n    </WiGrid>\n\n    <WiGrid :cols=\"2\" :x-gap=\"16\" :y-gap=\"16\">\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"年级人数\">\n          <WiTable :columns=\"recentColumns\" :rows=\"workflowTasks as unknown as Record<string, unknown>[]\" size=\"small\" :paginator=\"false\" bordered>\n            <template #cell-status=\"{ value }\">\n              <WiTag\n                :value=\"value === 'pending' ? '待审批' : value === 'approved' ? '已通过' : '已驳回'\"\n                :severity=\"value === 'pending' ? 'warn' : value === 'approved' ? 'success' : 'danger'\"\n              />\n            </template>\n          </WiTable>\n        </WiCard>\n      </WiGridItem>\n      <WiGridItem :span=\"1\">\n        <WiCard title=\"年级人数\">\n          <WiTable\n            :columns=\"[{ key: 'name', label: '课程' }, { key: 'enrolled', label: '人数', width: 72 }]\"\n            :rows=\"courses.slice(0, 4) as unknown as Record<string, unknown>[]\"\n            size=\"small\"\n            :paginator=\"false\"\n            bordered\n          />\n        </WiCard>\n      </WiGridItem>\n    </WiGrid>\n  </WiLayoutContent>\n</template>\n\n<style scoped>\n.dashboard {\n  padding: var(--wi-space-6);\n  display: flex;\n  flex-direction: column;\n  gap: var(--wi-space-6);\n}\n\n.dashboard__title {\n  margin: 0;\n  font-size: var(--wi-font-size-lg);\n  font-weight: 600;\n}\n\n.dashboard__stat {\n  box-shadow: var(--wi-shadow-sm);\n}\n\n.dashboard__stat-label {\n  margin: 0;\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-sm);\n}\n\n.dashboard__stat-value {\n  margin: var(--wi-space-1) 0;\n  font-size: 1.5rem;\n  font-weight: 700;\n}\n\n.dashboard__stat-trend {\n  margin: 0;\n  color: var(--wi-color-primary);\n  font-size: var(--wi-font-size-sm);\n}\n\n.dashboard__stat-icon {\n  color: var(--wi-color-primary);\n  opacity: 0.85;\n}\n\n.dashboard__bars {\n  display: flex;\n  align-items: flex-end;\n  gap: var(--wi-space-3);\n  min-height: 10rem;\n  padding-top: var(--wi-space-2);\n}\n\n.dashboard__bar-item {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: var(--wi-space-2);\n  height: 10rem;\n  justify-content: flex-end;\n  color: var(--wi-color-text-muted);\n  font-size: var(--wi-font-size-xs);\n}\n\n.dashboard__bar {\n  width: 100%;\n  max-width: 2.5rem;\n  border-radius: var(--wi-radius-sm) var(--wi-radius-sm) 0 0;\n  background: color-mix(in srgb, var(--wi-color-primary) 75%, transparent);\n}\n\n.dashboard__grades {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: grid;\n  gap: var(--wi-space-3);\n}\n\n.dashboard__grades li {\n  display: flex;\n  justify-content: space-between;\n  padding: var(--wi-space-3);\n  border: 1px solid var(--wi-color-border);\n  border-radius: var(--wi-radius-md);\n}\n</style>\n"
}

for (const [rel, content] of Object.entries(files)) {
  const target = join(root, rel)
  mkdirSync(dirname(target), { recursive: true })
  writeFileSync(target, content, 'utf8')
  console.log('wrote', rel)
}
